 def _validate_extraction_references(
     submission: PatientSubmission, extraction: TriageExtraction
 ) -> None:
     document_indices: set[int] = set()
     for fact in extraction.documents:
         if not 0 <= fact.source_index < len(submission.documents):
             raise ValueError(f"Extracted document index out of range: {fact.source_index}")
         if fact.source_index in document_indices:
             raise ValueError(f"Duplicate extracted document index: {fact.source_index}")
         document_indices.add(fact.source_index)
     medication_indices: set[int] = set()
     for fact in extraction.medications:
         if not 0 <= fact.medication_index < len(submission.medications):
             raise ValueError(
                 f"Extracted medication index out of range: {fact.medication_index}"
             )
         if fact.medication_index in medication_indices:
             raise ValueError(
                 f"Duplicate extracted medication index: {fact.medication_index}"
             )
         medication_indices.add(fact.medication_index)
     for plan in extraction.anticoagulation_plans:
         if not 0 <= plan.medication_index < len(submission.medications):
             raise ValueError(
                 f"Anticoagulation plan medication index out of range: "
                 f"{plan.medication_index}"
             )
         if not 0 <= plan.source_index < len(submission.documents):
